  (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate_vote:1240-marine-le-pen'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:marine-le-pen'), 'assemblee_nationale', '16e législature', '1240', 'Motion de censure transpartisane après le 49.3 sur la réforme des retraites', 'Motion déposée par Bertrand Pancher (groupe LIOT) et 90 de ses collègues, après l''engagement de la responsabilité du gouvernement d''Élisabeth Borne sur la réforme des retraites. Son adoption aurait entraîné la démission du gouvernement et le rejet du texte.', uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:retraites'), '2023-03-20', 'for', 'major', true, 'Assemblée nationale', 'https://www.assemblee-nationale.fr/dyn/16/scrutins/1240', 'parliament', 'published', '2026-09-10')
  on conflict (id) do nothing;
